{
  "name": "Teledyne LeCroy MAUI示波器",
  "name_en": "Teledyne LeCroy MAUI Oscilloscope",
  "manufacturer": "Teledyne LeCroy",
  "description": "这是一类采用 MAUI 用户界面的中高端数字示波器，用于采集、显示和分析电信号波形。它通常用于电子、电路、通信和实验室测试中，对触发、时基、通道波形、数学运算和自动测量进行观察与分析。",
  "description_en": "This is a family of medium- to high-end digital oscilloscopes using the MAUI user interface. It is used to acquire, display, and analyze electrical waveforms in electronics, circuits, communications, and laboratory testing, with support for triggering, timebase control, waveform viewing, math processing, and automated measurements.",
  "tag_hints": [
    "digital oscilloscope",
    "waveform acquisition",
    "triggered measurement",
    "timebase control",
    "oscilloscope math",
    "automated measurements",
    "high-bandwidth signal analysis"
  ],
  "actions": [
    {
      "action_name": "auto-clear_sweeps",
      "description": "清除测量扫掠累计。",
      "description_en": "Clear accumulated measurement sweeps."
    },
    {
      "action_name": "auto-force_trigger",
      "description": "强制产生一次触发事件。",
      "description_en": "Force a trigger event."
    },
    {
      "action_name": "auto-number_channels",
      "description": "获取/设置可用通道数量。",
      "description_en": "Get/set the number of available channels."
    },
    {
      "action_name": "auto-number_functions",
      "description": "获取/设置可用数学函数数量。",
      "description_en": "Get/set the number of available math functions."
    },
    {
      "action_name": "auto-number_measurements",
      "description": "获取/设置可用测量项数量。",
      "description_en": "Get/set the number of available measurements."
    },
    {
      "action_name": "auto-run",
      "description": "启动采集并使触发处于运行状态。",
      "description_en": "Start acquisition and enable triggering."
    },
    {
      "action_name": "auto-stop",
      "description": "停止采集并停止触发。",
      "description_en": "Stop acquisition and disable triggering."
    },
    {
      "action_name": "auto-time_div",
      "description": "获取/设置每格时间。",
      "description_en": "Get/set the time per division."
    },
    {
      "action_name": "auto-trigger_delay",
      "description": "获取/设置触发延迟。",
      "description_en": "Get/set the trigger delay."
    },
    {
      "action_name": "auto-trigger_source",
      "description": "获取/设置触发源。",
      "description_en": "Get/set the trigger source."
    },
    {
      "action_name": "auto-trigger_state",
      "description": "获取/设置触发状态。",
      "description_en": "Get/set the trigger state."
    },
    {
      "action_name": "auto-trigger_type",
      "description": "获取/设置触发类型。",
      "description_en": "Get/set the trigger type."
    },
    {
      "action_name": "auto-channel",
      "description": "获取示波器通道列表。",
      "description_en": "Get the oscilloscope channel list."
    },
    {
      "action_name": "auto-math",
      "description": "获取数学波形/函数列表。",
      "description_en": "Get the math waveform/function list."
    },
    {
      "action_name": "auto-measurement",
      "description": "获取测量项列表。",
      "description_en": "Get the measurement list."
    },
    {
      "action_name": "auto-ref",
      "description": "获取参考波形列表。",
      "description_en": "Get the reference waveform list."
    },
    {
      "action_name": "auto-self_test",
      "description": "运行示波器内部自检。",
      "description_en": "Run the oscilloscope internal self-test."
    },
    {
      "action_name": "auto-show_id",
      "description": "获取设备标识信息。",
      "description_en": "Get the device identification information."
    },
    {
      "action_name": "auto-show_options",
      "description": "获取已安装选件信息。",
      "description_en": "Get the installed options information."
    },
    {
      "action_name": "auto-name",
      "description": "获取/设置所选对象名称。",
      "description_en": "Get/set the name of the selected object."
    },
    {
      "action_name": "auto-read_waveform",
      "description": "读取所选通道或数据源的波形数据。",
      "description_en": "Read waveform data from the selected channel or source."
    },
    {
      "action_name": "auto-offset",
      "description": "获取/设置垂直偏置。",
      "description_en": "Get/set the vertical offset."
    },
    {
      "action_name": "auto-scale",
      "description": "获取/设置垂直刻度。",
      "description_en": "Get/set the vertical scale."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向示波器发送底层命令。",
      "description_en": "Send a low-level command to the oscilloscope."
    },
    {
      "action_name": "auto-query",
      "description": "向示波器发送查询并返回响应。",
      "description_en": "Send a query to the oscilloscope and return the response."
    },
    {
      "action_name": "auto-operator",
      "description": "获取/设置所选数学或测量对象的运算类型。",
      "description_en": "Get/set the operator type of the selected math or measurement object."
    },
    {
      "action_name": "auto-statistics",
      "description": "获取/设置测量统计设置。",
      "description_en": "Get/set the measurement statistics settings."
    },
    {
      "action_name": "auto-delete",
      "description": "删除所选函数、测量项或波形对象。",
      "description_en": "Delete the selected function, measurement, or waveform object."
    },
    {
      "action_name": "auto-set_parameter",
      "description": "设置所选函数或测量项的参数。",
      "description_en": "Set the parameter of the selected function or measurement."
    },
    {
      "action_name": "auto-current_setting",
      "description": "获取当前设置。",
      "description_en": "Get the current settings."
    },
    {
      "action_name": "auto-absolute",
      "description": "将所选数学函数设为绝对值运算。",
      "description_en": "Configure the selected math function as an absolute-value operation."
    },
    {
      "action_name": "auto-average",
      "description": "将所选数学函数设为平均运算。",
      "description_en": "Configure the selected math function as an averaging operation."
    },
    {
      "action_name": "auto-derivative",
      "description": "将所选数学函数设为微分运算。",
      "description_en": "Configure the selected math function as a derivative operation."
    },
    {
      "action_name": "auto-difference",
      "description": "将所选数学函数设为差分运算。",
      "description_en": "Configure the selected math function as a difference operation."
    },
    {
      "action_name": "auto-envelope",
      "description": "将所选数学函数设为包络运算。",
      "description_en": "Configure the selected math function as an envelope operation."
    },
    {
      "action_name": "auto-eres",
      "description": "将所选数学函数设为增强分辨率运算。",
      "description_en": "Configure the selected math function as an enhanced-resolution operation."
    },
    {
      "action_name": "auto-fft",
      "description": "将所选数学函数设为快速傅里叶变换。",
      "description_en": "Configure the selected math function as an FFT operation."
    },
    {
      "action_name": "auto-floor",
      "description": "将所选数学函数设为向下取整运算。",
      "description_en": "Configure the selected math function as a floor operation."
    },
    {
      "action_name": "auto-integral",
      "description": "将所选数学函数设为积分运算。",
      "description_en": "Configure the selected math function as an integral operation."
    },
    {
      "action_name": "auto-invert",
      "description": "将所选数学函数设为反相运算。",
      "description_en": "Configure the selected math function as an invert operation."
    },
    {
      "action_name": "auto-product",
      "description": "将所选数学函数设为乘积运算。",
      "description_en": "Configure the selected math function as a product operation."
    },
    {
      "action_name": "auto-ratio",
      "description": "将所选数学函数设为比值运算。",
      "description_en": "Configure the selected math function as a ratio operation."
    },
    {
      "action_name": "auto-reciprocal",
      "description": "将所选数学函数设为倒数运算。",
      "description_en": "Configure the selected math function as a reciprocal operation."
    },
    {
      "action_name": "auto-rescale",
      "description": "重新缩放所选波形或函数。",
      "description_en": "Rescale the selected waveform or function."
    },
    {
      "action_name": "auto-sinx",
      "description": "将所选数学函数设为 sinx 运算。",
      "description_en": "Configure the selected math function as a sinx operation."
    },
    {
      "action_name": "auto-square",
      "description": "将所选数学函数设为平方运算。",
      "description_en": "Configure the selected math function as a square operation."
    },
    {
      "action_name": "auto-square_root",
      "description": "将所选数学函数设为平方根运算。",
      "description_en": "Configure the selected math function as a square-root operation."
    },
    {
      "action_name": "auto-sum",
      "description": "将所选数学函数设为求和运算。",
      "description_en": "Configure the selected math function as a sum operation."
    },
    {
      "action_name": "auto-trend",
      "description": "将所选数学函数设为趋势运算。",
      "description_en": "Configure the selected math function as a trend operation."
    },
    {
      "action_name": "auto-roof",
      "description": "将所选数学函数设为向上取整运算。",
      "description_en": "Configure the selected math function as a ceiling operation."
    }
  ]
}

